/*!50001 VIEW `VI_game_mode_stats` AS select `gm`.`id` AS `game_mode_id`,`gm`.`name` AS `game_mode_name`,count(`r`.`id`) AS `game_mode_count`,sum((case when (`r`.`winning_party` = 'Re') then 1 else 0 end)) AS `re_wins`,round((sum((case when (`r`.`winning_party` = 'Re') then (case when (`gm`.`solo_party` = 'Re') then (3 * `r`.`points`) else `r`.`points` end) else (case when (`gm`.`solo_party` = 'Re') then (-(3) * `r`.`points`) else -(`r`.`points`) end) end)) / nullif(count(`r`.`id`),0)),2) AS `re_mean_points`,round((sum((case when (`r`.`winning_party` = 'Re') then 1 else 0 end)) / nullif(count(`r`.`id`),0)),4) AS `re_winrate` from ((`game_mode` `gm` left join `round_is_game_mode` `rigm` on((`gm`.`id` = `rigm`.`game_mode_id`))) left join `round` `r` on((`rigm`.`round_id` = `r`.`id`))) group by `gm`.`id`,`gm`.`name` */;
